package org.sleepwell.app;

import org.junit.Test;
import java.io.*;
import java.nio.charset.StandardCharsets;
import static org.junit.Assert.*;

public class MqttPublishTest {
    @Test public void publishesQoSOneNonRetainedAndWaitsCorrectAcknowledgement()throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();MqttPublish.exchange(new ByteArrayInputStream(new byte[]{0x20,2,0,0,0x40,2,0,1}),out,"sw-client","user","pass","sleep/events","{\"event_id\":\"abc\"}");DataInputStream in=new DataInputStream(new ByteArrayInputStream(out.toByteArray()));assertEquals(0x10,in.read());int length=in.read();byte[] connect=new byte[length];in.readFully(connect);DataInputStream fields=new DataInputStream(new ByteArrayInputStream(connect));assertEquals("MQTT",fields.readUTF());assertEquals(4,fields.read());assertEquals(0xc2,fields.read());assertEquals(15,fields.readUnsignedShort());assertEquals("sw-client",fields.readUTF());assertEquals("user",fields.readUTF());assertEquals("pass",fields.readUTF());assertEquals(-1,fields.read());assertEquals(0x32,in.read());length=in.read();byte[] publish=new byte[length];in.readFully(publish);fields=new DataInputStream(new ByteArrayInputStream(publish));assertEquals("sleep/events",fields.readUTF());assertEquals(1,fields.readUnsignedShort());assertEquals("{\"event_id\":\"abc\"}",new String(fields.readAllBytes(),StandardCharsets.UTF_8));assertEquals(0xe0,in.read());assertEquals(0,in.read());assertEquals(-1,in.read());}
    @Test public void anonymousConnectDoesNotSetCredentialFlags()throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();MqttPublish.exchange(new ByteArrayInputStream(new byte[]{0x20,2,0,0,0x40,2,0,1}),out,"sw-client","","","topic","{}");assertEquals(2,out.toByteArray()[9]);}
    @Test public void refusedConnectionDoesNotPublishOrLeakCredentials()throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();try{MqttPublish.exchange(new ByteArrayInputStream(new byte[]{0x20,2,0,5}),out,"client","sensitive-user","secret","topic","private-payload");fail();}catch(MqttPublish.Refused expected){assertFalse(expected.getMessage().contains("secret"));assertFalse(new String(out.toByteArray(),StandardCharsets.UTF_8).contains("private-payload"));}}
    @Test public void rejectsWrongPacketIdBeforeReportingDelivery()throws Exception{try{MqttPublish.exchange(new ByteArrayInputStream(new byte[]{0x20,2,0,0,0x40,2,0,2}),new ByteArrayOutputStream(),"client","","","topic","{}");fail();}catch(IOException expected){assertTrue(expected.getMessage().contains("mismatch"));}}
    @Test public void boundsMalformedOrOversizedReplies()throws Exception{for(byte[] response:new byte[][]{new byte[]{0x20,(byte)0xff,(byte)0xff,0x7f},new byte[]{0x20,2,0},new byte[]{0x30,0},new byte[]{0x20,(byte)0x80,(byte)0x80,(byte)0x80,(byte)0x80}}){try{MqttPublish.exchange(new ByteArrayInputStream(response),new ByteArrayOutputStream(),"client","","","topic","{}");fail();}catch(IOException expected){}}}
    @Test public void encodesRemainingLengthBeyondSingleByte()throws Exception{String payload="x".repeat(200);ByteArrayOutputStream out=new ByteArrayOutputStream();MqttPublish.exchange(new ByteArrayInputStream(new byte[]{0x20,2,0,0,0x40,2,0,1}),out,"c","","","t",payload);byte[] bytes=out.toByteArray();int index=2+(bytes[1]&255);assertEquals(0x32,bytes[index]);assertTrue((bytes[index+1]&128)!=0);assertEquals(1,bytes[index+2]);}
}
